('80000000-0000-0000-0000-000000000001', 'culture-explorer', 'DISTINCT_PARTNERS', '{"az": "Mədəniyyət kəşfiyyatçısı", "en": "Culture explorer"}'::jsonb, '{"az": "Bir ay ərzində 3 fərqli tərəfdaşdan alış edin.", "en": "Buy from 3 different partners within a calendar month."}'::jsonb, '{"az": "Xallar yalnız ödənilmiş və geri qaytarılmamış sifarişlər üçün verilir. Minimum sifariş məbləği 5 ₼. Geri qaytarma halında xallar ləğv edilir.", "en": "Points are awarded only for paid, non-refunded orders. Minimum order value 5 ₼. Points are reversed if the order is refunded."}'::jsonb, 3, 60, 'CALENDAR_MONTH', now() - interval '1 day', NULL, TRUE, 5.00, now(), now()),
('80000000-0000-0000-0000-000000000002', 'bundle-up', 'BUNDLE_PURCHASE', '{"az": "Paketlə qənaət", "en": "Bundle up"}'::jsonb, '{"az": "İlk paket təklifinizi alın.", "en": "Buy your first bundle offer."}'::jsonb, '{"az": "Xallar yalnız ödənilmiş və geri qaytarılmamış sifarişlər üçün verilir. Minimum sifariş məbləği 5 ₼. Geri qaytarma halında xallar ləğv edilir.", "en": "Points are awarded only for paid, non-refunded orders. Minimum order value 5 ₼. Points are reversed if the order is refunded."}'::jsonb, 1, 25, 'ONE_TIME', now() - interval '1 day', NULL, TRUE, 5.00, now(), now()),
('80000000-0000-0000-0000-000000000003', 'night-out', 'EVENT_ATTENDANCE', '{"az": "Axşam çıxışı", "en": "Night out"}'::jsonb, '{"az": "Bu ay bir tədbirdə iştirak edin (bilet tərəfdaş tərəfindən skan edilir).", "en": "Attend one event this month (your ticket is scanned by the partner)."}'::jsonb, '{"az": "Xallar yalnız ödənilmiş və geri qaytarılmamış sifarişlər üçün verilir. Minimum sifariş məbləği 5 ₼. Geri qaytarma halında xallar ləğv edilir.", "en": "Points are awarded only for paid, non-refunded orders. Minimum order value 5 ₼. Points are reversed if the order is refunded."}'::jsonb, 1, 20, 'CALENDAR_MONTH', now() - interval '1 day', NULL, TRUE, 5.00, now(), now()),
('80000000-0000-0000-0000-000000000004', 'something-new', 'NEW_CATEGORY', '{"az": "Yeni bir şey", "en": "Something new"}'::jsonb, '{"az": "Əvvəl almadığınız kateqoriyadan alış edin.", "en": "Buy from a category you have not bought from before."}'::jsonb, '{"az": "Xallar yalnız ödənilmiş və geri qaytarılmamış sifarişlər üçün verilir. Minimum sifariş məbləği 5 ₼. Geri qaytarma halında xallar ləğv edilir.", "en": "Points are awarded only for paid, non-refunded orders. Minimum order value 5 ₼. Points are reversed if the order is refunded."}'::jsonb, 1, 15, 'ONE_TIME', now() - interval '1 day', NULL, TRUE, 5.00, now(), now()),
('80000000-0000-0000-0000-000000000005', 'invite-a-friend', 'REFERRAL', '{"az": "Dostunu dəvət et", "en": "Invite a friend"}'::jsonb, '{"az": "Dəvət etdiyiniz dost ilk alışını tamamladıqda.", "en": "When a friend you invited completes their first purchase."}'::jsonb, '{"az": "Xallar yalnız ödənilmiş və geri qaytarılmamış sifarişlər üçün verilir. Minimum sifariş məbləği 5 ₼. Geri qaytarma halında xallar ləğv edilir.", "en": "Points are awarded only for paid, non-refunded orders. Minimum order value 5 ₼. Points are reversed if the order is refunded."}'::jsonb, 1, 50, 'ONE_TIME', now() - interval '1 day', NULL, TRUE, 5.00, now(), now());
